const data = { ...$json };

const missing = [];
const riskFlags = [];
const approval = [];

let riskScore = "Low";

const severity = {
  Low: 1,
  Medium: 2,
  High: 3,
  Critical: 4,
};

function raise(level) {
  if (severity[level] > severity[riskScore]) {
    riskScore = level;
  }
}

// -------------------------
// Missing Required Clauses
// -------------------------

if (!data.confidentiality_present) {
  missing.push("Confidentiality");
  riskFlags.push("Missing confidentiality clause");
  raise("Critical");
}

if (!data.ip_ownership_present) {
  missing.push("IP Ownership");
  riskFlags.push("Missing IP ownership clause");
  raise("Critical");
}

if (!data.termination_rights_present) {
  missing.push("Termination Rights");
  riskFlags.push("Missing termination rights clause");
  raise("High");
}

if (!data.data_security_present) {
  missing.push("Data Security");
  riskFlags.push("Missing data security clause");
  raise("High");
}

if (!data.data_privacy_present) {
  missing.push("Data Privacy");
  riskFlags.push("Missing data privacy clause");
  raise("High");
}

if (!data.sla_present) {
  missing.push("SLA");
  riskFlags.push("Missing SLA");
  raise("Medium");
}

if (!data.subcontracting_restriction_present) {
  missing.push("Subcontracting Restriction");
}

// -------------------------
// Approval Matrix
// -------------------------

const value = data.contract_value || 0;

if (value <= 25000) {
  approval.push("Department Manager");
} else if (value <= 50000) {
  approval.push("Legal");
} else {
  approval.push("Legal", "Finance");
}

if (data.customer_data_access) {
  approval.push("Security");
}

if (data.ai_or_cloud_services) {
  approval.push("Security");
}

if (data.international_vendor) {
  approval.push("Procurement");
}

// -------------------------
// Business Rules
// -------------------------

if (
  data.upfront_payment_percent !== null &&
  data.upfront_payment_percent > 20
) {
  riskFlags.push("Upfront payment exceeds 20%");
  raise("Medium");
}

if (
  data.payment_terms_net_days !== null &&
  data.payment_terms_net_days > 45
) {
  riskFlags.push("Payment terms exceed Net 45");
  raise("Medium");
}

if (
  data.warranty_days !== null &&
  data.warranty_days < 90
) {
  riskFlags.push("Warranty less than 90 days");
  raise("High");
}

if (
  data.governing_law &&
  data.governing_law.toLowerCase() !== "texas"
) {
  riskFlags.push("Governing law outside Texas");
  raise("Medium");
}

if (data.unlimited_vendor_liability) {
  riskFlags.push("Unlimited vendor liability");
  raise("High");
}

if (data.vendor_owns_custom_software) {
  riskFlags.push("Vendor retains ownership of custom software");
  raise("High");
}

if (data.indemnification_vendor_favored) {
  riskFlags.push("Vendor-favored indemnification");
  raise("High");
}

if (data.exclusivity_clause) {
  riskFlags.push("Exclusivity clause present");
  raise("Medium");
}

if (data.non_compete_clause) {
  riskFlags.push("Non-compete clause present");
  raise("Medium");
}

if (
  data.automatic_renewal_months !== null &&
  data.automatic_renewal_months > 12
) {
  riskFlags.push("Automatic renewal exceeds 12 months");
  raise("Medium");
}

// -------------------------

data.missing_required_clauses = missing;
data.risk_flags = [...new Set(riskFlags)];
data.risk_score = riskScore;
data.approval_route = [...new Set(approval)];

return [
  {
    json: data,
  },
];

const raw = $json.output?.[0]?.content?.[0]?.text || "";

const cleaned = raw
  .replace(/^```json/i, "")
  .replace(/^```/, "")
  .replace(/```$/, "")
  .trim();

return [
  {
    json: JSON.parse(cleaned)
  }
];
